using FluentAssertions; using MongoDB.Bson; using MongoDB.Driver; using Testcontainers.MongoDb;
namespace EduManageLms.Tests;
public sealed class MongoAggregationIntegrationTests:IAsyncLifetime { private readonly MongoDbContainer mongo=new MongoDbBuilder().WithImage("mongo:7.0").Build(); private IMongoCollection<BsonDocument> students=null!; public async Task InitializeAsync(){await mongo.StartAsync();students=new MongoClient(mongo.GetConnectionString()).GetDatabase("test").GetCollection<BsonDocument>("students");await students.InsertOneAsync(BsonDocument.Parse("{studentCode:'SV001',academicRecords:[{semesters:[{courses:[{courseCode:'NOSQL01',credits:3,scores:[{weight:40,maxScore:10,score:8},{weight:60,maxScore:20,score:14}]}]}]}]}"));} public Task DisposeAsync()=>mongo.DisposeAsync().AsTask(); [Fact] public async Task Mongo_pipeline_calculates_weighted_course_score(){var p=new[]{new BsonDocument("$match",new BsonDocument("studentCode","SV001")),new BsonDocument("$unwind","$academicRecords"),new BsonDocument("$unwind","$academicRecords.semesters"),new BsonDocument("$unwind","$academicRecords.semesters.courses"),new BsonDocument("$unwind","$academicRecords.semesters.courses.scores"),new BsonDocument("$group",new BsonDocument{{"_id","$academicRecords.semesters.courses.courseCode"},{"final",new BsonDocument("$sum",new BsonDocument("$multiply",new BsonArray{new BsonDocument("$divide",new BsonArray{"$academicRecords.semesters.courses.scores.score","$academicRecords.semesters.courses.scores.maxScore"}),10,new BsonDocument("$divide",new BsonArray{"$academicRecords.semesters.courses.scores.weight",100})}))}})};var result=await students.Aggregate<BsonDocument>(p).SingleAsync();result["final"].ToDouble().Should().BeApproximately(7.4,.001);}}
